head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil17302";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — qnaList
// TODO Stage2: 세션 키 실환경 확인(회신 11항 · user-info 계약에 없는 키) — session.user.usrId

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        scwin.init_conds();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil17302.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "img_52", fn: function(){ return ((dlt_qnaList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '1'); } }, { id: "img_54", fn: function(){ return ((dlt_qnaList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '2'); } }, { id: "img_56", fn: function(){ return ((dlt_qnaList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '3'); } }, { id: "img_58", fn: function(){ return ((dlt_qnaList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '4'); } }, { id: "img_60", fn: function(){ return ((dlt_qnaList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '6'); } }, { id: "c_otherwise_61", fn: function(){ return (!(((dlt_qnaList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '1') || ((dlt_qnaList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '2') || ((dlt_qnaList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '3') || ((dlt_qnaList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '4') || ((dlt_qnaList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '6'))); } }, { id: "if_attachFileNm", fn: function(){ return (!(String(((dlt_qnaList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })())) == null ? '' : ((dlt_qnaList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })()))).length === 0)); } }, { id: "tr_46", fn: function(){ return (!(String(((dlt_qnaList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })())) == null ? '' : ((dlt_qnaList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })()))).length === 0)); } }, { id: "c_when_23", fn: function(){ return ((dlt_qnaList.getCellData(0, "quesAnsTpCd") ?? (() => { throw new Error("unresolved:" + "entity.quesAnsTpCd"); })()) === '1'); } }, { id: "if_attachFileNm_2", fn: function(){ return (!(String(((dlt_qnaList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })())) == null ? '' : ((dlt_qnaList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })()))).length === 0)); } }, { id: "tr_76", fn: function(){ return (!(String(((dlt_qnaList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })())) == null ? '' : ((dlt_qnaList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })()))).length === 0)); } }, { id: "c_when_64", fn: function(){ return ((dlt_qnaList.getCellData(0, "quesAnsTpCd") ?? (() => { throw new Error("unresolved:" + "entity.quesAnsTpCd"); })()) === '2'); } }, { id: "btn_modify", fn: function(){ return ((((dma_pageContext.get("qnaList") ?? "")) && typeof ((dma_pageContext.get("qnaList") ?? "")).getRowCount === 'function' ? ((dma_pageContext.get("qnaList") ?? "")).getRowCount() : ((((dma_pageContext.get("qnaList") ?? "")) == null) ? 0 : (((dma_pageContext.get("qnaList") ?? "")).length || 0))) === 1 && (dlt_qnaList.getCellData(0, "quesAnsTpCd") ?? (() => { throw new Error("unresolved:" + "entity.quesAnsTpCd"); })()) === '1' && (dlt_qnaList.getCellData(0, "questrId") ?? (() => { throw new Error("unresolved:" + "entity.questrId"); })()) === $c.session.getUserInfo("usrId")); } }, { id: "btn_delete", fn: function(){ return ((((dma_pageContext.get("qnaList") ?? "")) && typeof ((dma_pageContext.get("qnaList") ?? "")).getRowCount === 'function' ? ((dma_pageContext.get("qnaList") ?? "")).getRowCount() : ((((dma_pageContext.get("qnaList") ?? "")) == null) ? 0 : (((dma_pageContext.get("qnaList") ?? "")).length || 0))) === 1 && (dlt_qnaList.getCellData(0, "quesAnsTpCd") ?? (() => { throw new Error("unresolved:" + "entity.quesAnsTpCd"); })()) === '1' && (dlt_qnaList.getCellData(0, "questrId") ?? (() => { throw new Error("unresolved:" + "entity.questrId"); })()) === $c.session.getUserInfo("usrId")); } }, { id: "c_when_18", fn: function(){ return (!(String(((dma_pageContext.get("qnaList") ?? "")) == null ? '' : ((dma_pageContext.get("qnaList") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_20", entity: "dlt_qnaList", countIds: [], rowConds: [{"childId":"c_if_95","kind":"last"}], cells: [{ childId: "__rc0", fn: function (v, i) { return String(v("comNm")); } }, { childId: "__rc1", fn: function (v, i) { return String(v("questrNm")); } }, { childId: "__rc2", fn: function (v, i) { return String(v("regDdtm")); } }, { childId: "__rc3", fn: function (v, i) { return " " + String(v("quesTitle")); } }, { childId: "__rc4", fn: function (v, i) { return String(v("quesContn")); } }, { childId: "__rc5", fn: function (v, i) { return " " + String(v("attachFileNm")); } }, { childId: "__rc6", fn: function (v, i) { return " " + String(v("quesTitle")); } }, { childId: "__rc7", fn: function (v, i) { return String(v("quesContn")); } }, { childId: "__rc8", fn: function (v, i) { return " " + String(v("attachFileNm")); } }, { childId: "__rc9", fn: function (v, i) { return String(v("questrNm")) + " ("; } }, { childId: "__rc10", fn: function (v, i) { return String(v("questrTelNo")) + ")"; } }, { childId: "__rc11", fn: function (v, i) { return String(v("regDdtm")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_delete();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_FileDown_onclick
 * @description btn_FileDown 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_FileDown_onclick = async function(e){
    try {
        await scwin.fileDown('' + dlt_qnaList.getCellData(0, "contnId") + '','' + dlt_qnaList.getCellData(0, "contnAttachSeq") + '','' + dlt_qnaList.getCellData(0, "attachFileNm") + '')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil17302.btn_FileDown_onclick' }); }
};

/**
 * @method
 * @name btn_FileDown_2_onclick
 * @description btn_FileDown_2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_FileDown_2_onclick = async function(e){
    try {
        await scwin.fileDown('' + dlt_qnaList.getCellData(0, "contnId") + '','' + dlt_qnaList.getCellData(0, "contnAttachSeq") + '','' + dlt_qnaList.getCellData(0, "attachFileNm") + '')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil17302.btn_FileDown_2_onclick' }); }
};

/**
 * @method
 * @name btn_modify_onclick
 * @description 「수정」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_modify_onclick = async function(e){
    try {
        await scwin.modify('' + dma_pageContext.get("contnId") + '','' + dma_pageContext.get("contnAttachSeq") + '')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil17302.btn_modify_onclick' }); }
};

/**
 * @method
 * @name btn_delete_onclick
 * @description 「삭제」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_delete_onclick = async function(e){
    try {
        await scwin.deleteGoListReq('' + dma_pageContext.get("contnId") + '','' + dma_pageContext.get("contnAttachSeq") + '')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil17302.btn_delete_onclick' }); }
};

/**
 * @method
 * @name btn_goList_onclick
 * @description 「목록」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_goList_onclick = async function(e){
    try {
        await scwin.goList()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil17302.btn_goList_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_goList
 * @description go List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goList = async function () {
    const sbmOptions = {
        id: "tx_fn_goList",
        method: "post",
        action: "/support/qna.do",
        ref: "dma_goListReq",
        target: "dlt_qnaList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_delete
 * @description delete 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_delete = async function () {
    const sbmOptions = {
        id: "tx_fn_delete",
        method: "post",
        action: "/support/qna.do",
        ref: "dma_deleteReq",
        target: "dlt_qnaList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_modify
 * @description modify 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_modify = async function () {
    const sbmOptions = {
        id: "tx_fn_modify",
        method: "post",
        action: "/support/qna.do",
        ref: "dma_modifyReq",
        target: "dlt_qnaList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_FileDown
 * @description File Down 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_FileDown = async function () {
    try { return await $c.data.downFile("/support/filedownqna.do", "", ($c.util.getComponent("dma_FileDownReq") ? $c.util.getComponent("dma_FileDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name goList
 * @description go List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goList = async function () {
    const frm = (document.QnaViewForm || { elements: [] });
    frm.action = 'qna.do';
    $c.util.getComponent('dma_goListReq').set('method', 'searchQnaList');
    const nr = await scwin.tx_fn_goList();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil17300/jldfil17300.xml", { "method": 'searchQnaList' });
    }
};

/**
 * @method
 * @name deleteGoListReq
 * @description delete Go List Req 처리
 * @param {String} contnId contnId
 * @param {*} contnAttachSeq contnAttachSeq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.deleteGoListReq = async function (contnId, contnAttachSeq) {
    const frm = (document.QnaViewForm || { elements: [] });
    frm.action = 'qna.do';
    $c.util.getComponent('dma_goListReq').set('method', 'deleteQuestion');
    $c.util.getComponent('dma_goListReq').set('contnId', contnId);
    $c.util.getComponent('dma_goListReq').set('contnAttachSeq', contnAttachSeq);
    await scwin.tx_fn_delete();
};

/**
 * @method
 * @name modify
 * @description modify 처리
 * @param {String} contnId contnId
 * @param {*} contnAttachSeq contnAttachSeq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.modify = async function (contnId, contnAttachSeq) {
    const frm = (document.QnaViewForm || { elements: [] });
    frm.action = 'qna.do';
    $c.util.getComponent('dma_goListReq').set('method', 'modifyQna');
    $c.util.getComponent('dma_goListReq').set('contnId', contnId);
    $c.util.getComponent('dma_goListReq').set('contnAttachSeq', contnAttachSeq);
    $c.util.getComponent('dma_goListReq').set('modifyYn', 'Y');
    const nr = await scwin.tx_fn_modify();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil17301/jldfil17301.xml", { "method": 'modifyQna', "contnId": contnId, "contnAttachSeq": contnAttachSeq, "modifyYn": 'Y' });
    }
};

/**
 * @method
 * @name fileDown
 * @description file Down 처리
 * @param {String} contnId contnId
 * @param {*} contnAttachSeq contnAttachSeq
 * @param {String} attachFileNm attachFileNm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileDown = async function (contnId, contnAttachSeq, attachFileNm) {
    const frm = (document.QnaViewForm || { elements: [] });
    frm.action = 'filedownqna.do';
    $c.util.getComponent('dma_goListReq').set('method', 'searchQnaFile');
    $c.util.getComponent('dma_goListReq').set('contnId', contnId);
    $c.util.getComponent('dma_goListReq').set('contnAttachSeq', contnAttachSeq);
    $c.util.getComponent('dma_goListReq').set('attachFileNm', attachFileNm);
    await scwin.tx_fn_FileDown();
};
